/**
 * Метка сборки. Подставляется Vite (см. `define` в vite.config.ts):
 * короткий git sha, а вне git-дерева — 'dev'.
 * Уходит в файл выгрузки параметров, чтобы было видно, чем он сделан.
 */
declare const __APP_VERSION__: string | undefined

/**
 * Адрес хранилища на сервере. В публичном репозитории ПУСТОЙ: значение
 * подставляется при сборке из переменной окружения PUBLIC_API_BASE.
 * Если она не задана, адрес вводится в самом пульте и живёт в браузере.
 */
declare const __API_BASE__: string | undefined
